function akarBulat(n) {
  let lo = 0, hi = n, ans = 0;
  while (lo <= hi) {
    const mid = Math.floor((lo + hi) / 2);
    if (mid * mid <= n) { ans = mid; lo = mid + 1; }
    else hi = mid - 1;
  }
  return ans;
}

