func akarBulat(n int) int {
	kiri, kanan := 0, n
	for kiri < kanan {
		tengah := (kiri + kanan + 1) / 2
		if tengah*tengah <= n {
			kiri = tengah
		} else {
			kanan = tengah - 1
		}
	}
	return kiri
}
